 51	    /**
 52	     * This is what the Grass does most of the time - it grows 
 53	     * around. Sometimes it will breed or die of steppeFire. If
 54	     * the grass catches fire, it will also burn the unit adjacent to it 
 55	     * @param step The current simulation step.
 56	     */
 57	    public void act(List<Organism> newOrganisms, SimulationStep step)
 58	    {
 59	        if(isAlive()) {
 60	            if(step.getWeather() == Weather.RAINY) {
 61	                incrementSize();
 62	                steppeFired = false;
 63	            }
 64	            else {
 65	                ignite();
 66	                if(steppeFire()) {
 67	                    forEachAdjacent(Grass.class, 1, Grass::ignite);
 68	                    forEachAdjacent(Animal.class, 1, Animal::burn);
 69	                    decrementSize();                
 70	                }
 71	            }
 72	        }
 73	    }
